/**
 *
 * Divider is used to separate contents.
 *
 * [Live Demo](https://primevue.dev/divider)
 *
 * @module dividerstyle
 *
 */
import type { BaseStyle, BaseStyleModule } from '@primevue/core/base/style';

export enum DividerClasses {
    /**
     * Class name of the root element
     */
    root = 'p-divider',
    /**
     * Class name of the content element
     */
    content = 'p-divider-content'
}

export interface DividerStyle extends BaseStyle {}

declare const DividerStyle: BaseStyleModule;

export default DividerStyle;
